#!/usr/bin/env bash
# Applies the Kafka ACLs of deploy/kafka/acls.txt (generated by scripts/kafka_acls.py, ADR-0029). Idempotent: adding
# an ACL that exists changes nothing. ACLs no longer in the file are reported, not removed (remove them by hand after
# checking nothing needs them).
#
#   KAFKA_NETWORK=<docker network> KAFKA_BROKER_PASSWORD=... deploy/vps/kafka-acls.sh <acls.txt>
#
# The broker image (kafka-native) has no CLI, so the JVM image's kafka-acls.sh runs in a one-off container on the
# broker's network, as the broker's super user.
set -euo pipefail

ACLS="$(cd "$(dirname "${1:?acls.txt}")" && pwd)/$(basename "$1")"
NETWORK="${KAFKA_NETWORK:?set KAFKA_NETWORK to the docker network of the broker}"
BOOTSTRAP="${KAFKA_BOOTSTRAP:-kafka:9092}"
IMAGE="${KAFKA_CLI_IMAGE:-apache/kafka:3.8.0}"
: "${KAFKA_BROKER_PASSWORD:?}"

work="$(mktemp -d)"; trap 'rm -rf "$work"' EXIT
chmod 755 "$work"
( umask 077
  cat > "$work/admin.properties" <<PROPS
security.protocol=SASL_PLAINTEXT
sasl.mechanism=PLAIN
sasl.jaas.config=org.apache.kafka.common.security.plain.PlainLoginModule required username="broker" password="${KAFKA_BROKER_PASSWORD}";
PROPS
)
chmod 644 "$work/admin.properties"

# One kafka-acls.sh call per principal, resource type, pattern type and operation, with all its resources.
python3 - "$ACLS" > "$work/commands.sh" <<'PY'
import collections, shlex, sys
groups = collections.defaultdict(list)
for line in open(sys.argv[1], encoding="utf-8"):
    line = line.strip()
    if not line or line.startswith("#"):
        continue
    principal, op, rtype, ptype, name = line.split()
    groups[(principal, op, rtype, ptype)].append(name)
print("set -e")
for (principal, op, rtype, ptype), names in sorted(groups.items()):
    flag = "--topic" if rtype == "TOPIC" else "--group"
    resources = " ".join(f"{flag} {shlex.quote(n)}" for n in sorted(names))
    print(f'echo "{principal} {op} {rtype} {ptype}: {len(names)}"')
    print(f"/opt/kafka/bin/kafka-acls.sh --bootstrap-server \"$BOOTSTRAP\" --command-config /work/admin.properties"
          f" --add --allow-principal {shlex.quote(principal)} --operation {op} --resource-pattern-type {ptype.lower()}"
          f" {resources} > /dev/null")
print('echo "--- ACLs on the broker now:"')
print('/opt/kafka/bin/kafka-acls.sh --bootstrap-server "$BOOTSTRAP" --command-config /work/admin.properties --list'
      ' | grep -c "principal=User:" || true')
PY

docker run --rm --network "$NETWORK" -e BOOTSTRAP="$BOOTSTRAP" -v "$work:/work:ro" --entrypoint bash "$IMAGE" /work/commands.sh
